  /*
   {"diagramJson": "{\"title\":\"Film scouting \\u00b7 2. Logistics: incentives, airports, lodging, healthcare\",\"description\":\"Adds state, county and film incentives (from the uploaded film_incentives table), the nearest airport and hospital, and hotels and healthcare within about an hour to each scouting area. Saves the final film_scout_scoring table the tools read.\",\"nodes\":[{\"id\":\"s1\",\"data\":{\"id\":\"YOUR_PROJECT.YOUR_DATASET.film_scout_landscape\",\"name\":\"ReadTable\",\"type\":\"table\",\"label\":\"film_scout_landscape\",\"inputs\":[{\"name\":\"source\",\"type\":\"String\",\"title\":\"Source table\",\"value\":\"YOUR_PROJECT.YOUR_DATASET.film_scout_landscape\",\"description\":\"Read Table\"}]},\"type\":\"source\",\"position\":{\"x\":432,\"y\":-32}},{\"id\":\"n2\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"area_id, `carto-un`.carto.H3_CENTER(area_id) AS center\",\"description\":\"SELECT statement\",\"placeholder\":\"E.g.: *, distance_in_km * 1000 AS distance_in_meters\",\"allowExpressions\":false}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":672,\"y\":0}},{\"id\":\"s3\",\"data\":{\"id\":\"carto-do-public-data.usa_tiger.geography_usa_county_2024\",\"name\":\"ReadTable\",\"type\":\"table\",\"label\":\"geography_usa_county_2024\",\"inputs\":[{\"name\":\"source\",\"type\":\"String\",\"title\":\"Source table\",\"value\":\"carto-do-public-data.usa_tiger.geography_usa_county_2024\",\"description\":\"Read Table\"}]},\"type\":\"source\",\"position\":{\"x\":896,\"y\":-112}},{\"id\":\"n4\",\"data\":{\"name\":\"native.customsql\",\"type\":\"generic\",\"label\":\"Custom SQL Select\",\"inputs\":[{\"name\":\"sourcea\",\"type\":\"Table\",\"title\":\"Source table a\",\"optional\":true,\"description\":\"Source table a\"},{\"name\":\"sourceb\",\"type\":\"Table\",\"title\":\"Source table b\",\"optional\":true,\"description\":\"Source table b\"},{\"name\":\"sourcec\",\"type\":\"Table\",\"title\":\"Source table c\",\"optional\":true,\"description\":\"Source table c\"},{\"mode\":\"multiline\",\"name\":\"sql\",\"type\":\"StringSql\",\"title\":\"SQL SELECT statement\",\"value\":\"SELECT CONCAT(NAMELSAD, ', ', CASE STATEFP WHEN '53' THEN 'WA' WHEN '41' THEN 'OR' WHEN '16' THEN 'ID' WHEN '30' THEN 'MT' WHEN '56' THEN 'WY' WHEN '06' THEN 'CA' WHEN '32' THEN 'NV' WHEN '49' THEN 'UT' WHEN '08' THEN 'CO' WHEN '04' THEN 'AZ' WHEN '35' THEN 'NM' END) AS county_state, geom\\nFROM `$a`\\nWHERE STATEFP IN ('53', '41', '16', '30', '56', '06', '32', '49', '08', '04', '35')\",\"description\":\"SQL SELECT statement\",\"placeholder\":\"SELECT ST_Centroid(geom) AS geom,\\n  AVG(value) AS average_value,\\n  category\\nFROM $a\\nGROUP BY category\",\"allowExpressions\":false}],\"version\":\"2.0.0\"},\"type\":\"generic\",\"zIndex\":2,\"position\":{\"x\":1136,\"y\":-80}},{\"id\":\"n5\",\"data\":{\"name\":\"native.distance\",\"type\":\"generic\",\"label\":\"Distance to nearest\",\"inputs\":[{\"name\":\"main\",\"type\":\"Table\",\"title\":\"Main table\",\"description\":\"Main table\"},{\"name\":\"secondary\",\"type\":\"Table\",\"title\":\"Secondary table\",\"description\":\"Secondary table\"},{\"name\":\"geomain\",\"type\":\"Column\",\"title\":\"Geo column in main table\",\"value\":\"center\",\"parent\":\"main\",\"dataType\":[\"geography\"],\"description\":\"Geo column in main table\"},{\"name\":\"geosecondary\",\"type\":\"Column\",\"title\":\"Geo column in secondary table\",\"value\":\"geom\",\"parent\":\"secondary\",\"dataType\":[\"geography\"],\"description\":\"Geo column in secondary table\"},{\"name\":\"idmain\",\"type\":\"Column\",\"title\":\"Id column in main table\",\"value\":\"area_id\",\"parent\":\"main\",\"description\":\"Id column in main table\"},{\"name\":\"idsecondary\",\"type\":\"Column\",\"title\":\"Id column in secondary table\",\"value\":\"county_state\",\"parent\":\"secondary\",\"description\":\"Id column in secondary table\"},{\"min\":0,\"name\":\"radius\",\"type\":\"Number\",\"title\":\"Radius\",\"value\":100,\"description\":\"Radius\"},{\"name\":\"units\",\"type\":\"Selection\",\"title\":\"Units\",\"value\":\"Miles\",\"default\":\"Meters\",\"options\":[\"Meters\",\"Miles\"],\"description\":\"Units\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":944,\"y\":288}},{\"id\":\"s6\",\"data\":{\"id\":\"YOUR_PROJECT.YOUR_DATASET.film_incentives\",\"name\":\"ReadTable\",\"type\":\"table\",\"label\":\"film_incentives\",\"inputs\":[{\"name\":\"source\",\"type\":\"String\",\"title\":\"Source table\",\"value\":\"YOUR_PROJECT.YOUR_DATASET.film_incentives\",\"description\":\"Read Table\"}]},\"type\":\"source\",\"position\":{\"x\":896,\"y\":200}},{\"id\":\"n7\",\"data\":{\"name\":\"native.joinv2\",\"type\":\"generic\",\"label\":\"Join\",\"inputs\":[{\"name\":\"lefttable\",\"type\":\"Table\",\"title\":\"Left table\",\"description\":\"Left table\"},{\"name\":\"righttable\",\"type\":\"Table\",\"title\":\"Right table\",\"description\":\"Right table\"},{\"name\":\"lefttablekeycolumn\",\"type\":\"Column\",\"title\":\"Key column in left table\",\"value\":\"nearest_id\",\"parent\":\"lefttable\",\"dataType\":[\"boolean\",\"date\",\"datetime\",\"time\",\"timestamp\",\"number\",\"string\"],\"description\":\"Key column in left table\"},{\"name\":\"lefttablecolumns\",\"type\":\"ColumnsForJoin\",\"title\":\"Left table columns\",\"value\":\"[{\\\"name\\\": \\\"area_id\\\", \\\"joinname\\\": \\\"area_id\\\"}, {\\\"name\\\": \\\"center\\\", \\\"joinname\\\": \\\"center\\\"}]\",\"parent\":\"lefttable\",\"optional\":true,\"description\":\"Left table columns\"},{\"name\":\"righttablekeycolumn\",\"type\":\"Column\",\"title\":\"Key column in right table\",\"value\":\"county_state\",\"parent\":\"righttable\",\"dataType\":[\"boolean\",\"date\",\"datetime\"