ional|airport|sunport')\\nAND NOT REGEXP_CONTAINS(LOWER(names.primary), r'municipal|executive|aviation|check-in|car rental|rental|parking|terminal|heliport|helipad|airstrip|seaplane|ranch|private|fbo|hangar|flight|shuttle|lounge|cargo|security|tsa|baggage|museum|restaurant|hotel|air force|army|naval|ultralight|glider|skypark|sky park|airpark|air park|state airport|memorial airport$')\\nAND ST_INTERSECTS(geom, ST_GEOGFROMTEXT('POLYGON((-125.5 30.5,-101.5 30.5,-101.5 50,-125.5 50,-125.5 30.5))'))\",\"description\":\"SQL SELECT statement\",\"placeholder\":\"SELECT ST_Centroid(geom) AS geom,\\n  AVG(value) AS average_value,\\n  category\\nFROM $a\\nGROUP BY category\",\"allowExpressions\":false}],\"version\":\"2.0.0\"},\"type\":\"generic\",\"zIndex\":2,\"position\":{\"x\":1552,\"y\":224}},{\"id\":\"n11\",\"data\":{\"name\":\"native.distance\",\"type\":\"generic\",\"label\":\"Distance to nearest\",\"inputs\":[{\"name\":\"main\",\"type\":\"Table\",\"title\":\"Main table\",\"description\":\"Main table\"},{\"name\":\"secondary\",\"type\":\"Table\",\"title\":\"Secondary table\",\"description\":\"Secondary table\"},{\"name\":\"geomain\",\"type\":\"Column\",\"title\":\"Geo column in main table\",\"value\":\"center\",\"parent\":\"main\",\"dataType\":[\"geography\"],\"description\":\"Geo column in main table\"},{\"name\":\"geosecondary\",\"type\":\"Column\",\"title\":\"Geo column in secondary table\",\"value\":\"geom\",\"parent\":\"secondary\",\"dataType\":[\"geography\"],\"description\":\"Geo column in secondary table\"},{\"name\":\"idmain\",\"type\":\"Column\",\"title\":\"Id column in main table\",\"value\":\"area_id\",\"parent\":\"main\",\"description\":\"Id column in main table\"},{\"name\":\"idsecondary\",\"type\":\"Column\",\"title\":\"Id column in secondary table\",\"value\":\"airport_name\",\"parent\":\"secondary\",\"description\":\"Id column in secondary table\"},{\"min\":0,\"name\":\"radius\",\"type\":\"Number\",\"title\":\"Radius\",\"value\":300,\"description\":\"Radi