jul_sun_mj\\\", \\\"joinname\\\": \\\"jul_sun_mj\\\"}, {\\\"name\\\": \\\"aug_sun_mj\\\", \\\"joinname\\\": \\\"aug_sun_mj\\\"}, {\\\"name\\\": \\\"sep_sun_mj\\\", \\\"joinname\\\": \\\"sep_sun_mj\\\"}, {\\\"name\\\": \\\"oct_sun_mj\\\", \\\"joinname\\\": \\\"oct_sun_mj\\\"}, {\\\"name\\\": \\\"nov_sun_mj\\\", \\\"joinname\\\": \\\"nov_sun_mj\\\"}, {\\\"name\\\": \\\"dec_sun_mj\\\", \\\"joinname\\\": \\\"dec_sun_mj\\\"}, {\\\"name\\\": \\\"hotels_tourism_pois\\\", \\\"joinname\\\": \\\"hotels_tourism_pois\\\"}, {\\\"name\\\": \\\"healthcare_pois\\\", \\\"joinname\\\": \\\"healthcare_pois\\\"}, {\\\"name\\\": \\\"restaurant_pois\\\", \\\"joinname\\\": \\\"restaurant_pois\\\"}, {\\\"name\\\": \\\"population\\\", \\\"joinname\\\": \\\"population\\\"}, {\\\"name\\\": \\\"map_cells\\\", \\\"joinname\\\": \\\"map_cells\\\"}, {\\\"name\\\": \\\"r8_cells\\\", \\\"joinname\\\": \\\"r8_cells\\\"}]\",\"parent\":\"lefttable\",\"optional\":true,\"description\":\"Left table columns\"},{\"name\":\"righttablekeycolumn\",\"type\":\"Column\",\"title\":\"Key column in right table\",\"value\":\"area_id\",\"parent\":\"righttable\",\"dataType\":[\"boolean\",\"date\",\"datetime\",\"time\",\"timestamp\",\"number\",\"string\"],\"description\":\"Key column in right table\"},{\"name\":\"righttablecolumns\",\"type\":\"ColumnsForJoin\",\"title\":\"Right table columns\",\"value\":\"[{\\\"name\\\": \\\"state\\\", \\\"joinname\\\": \\\"state\\\"}, {\\\"name\\\": \\\"county\\\", \\\"joinname\\\": \\\"county\\\"}, {\\\"name\\\": \\\"area_name\\\", \\\"joinname\\\": \\\"area_name\\\"}, {\\\"name\\\": \\\"credit_base_pct\\\", \\\"joinname\\\": \\\"credit_base_pct\\\"}, {\\\"name\\\": \\\"credit_uplift_pct\\\", \\\"joinname\\\": \\\"credit_uplift_pct\\\"}, {\\\"name\\\": \\\"incentive_pct\\\", \\\"joinname\\\": \\\"incentive_pct\\\"}, {\\\"name\\\": \\\"incentive_note\\\", \\\"joinname\\\": \\\"incentive_note\\\"}, {\\\"name\\\": \\\"nearest_hospital\\\", \\\"joinname\\\": \\\"nearest_hospital\\\"}, {\\\"name\\\": \\\"nearest_hospital_mi\\\", \\\"joinname\\\": \\\"nearest_hospital_mi\\\"}, {\\\"name\\\": \\\"hotels_nearby\\\", \\\"joinname\\\": \\\"hotels_nearby\\\"}, {\\\"name\\\": \\\"healthcare_nearby\\\", \\\"joinname\\\": \\\"healthcare_nearby\\\"}, {\\\"name\\\": \\\"nearest_airport\\\", \\\"joinname\\\": \\\"nearest_airport\\\"}, {\\\"name\\\": \\\"nearest_airport_mi\\\", \\\"joinname\\\": \\\"nearest_airport_mi\\\"}]\",\"parent\":\"righttable\",\"optional\":true,\"description\":\"Right table columns\"},{\"name\":\"jointype\",\"type\":\"Selection\",\"title\":\"Join type\",\"value\":\"Left\",\"default\":\"Inner\",\"options\":[\"Inner\",\"Left\",\"Right\",\"Full outer\"],\"description\":\"Join type\"},{\"name\":\"whereclause\",\"type\":\"StringSql\",\"title\":\"Where clause\",\"advanced\":true,\"optional\":true,\"description\":\"Where clause\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":3168,\"y\":0}},{\"id\":\"n19\",\"data\":{\"name\":\"native.saveastable\",\"type\":\"generic\",\"label\":\"Save as Table\",\"inputs\":[{\"name\":\"source\",\"type\":\"Table\",\"title\":\"Source table\",\"description\":\"Source table\"},{\"name\":\"destination\",\"type\":\"OutputTable\",\"title\":\"Table details\",\"value\":\"YOUR_PROJECT.YOUR_DATASET.film_scout_scoring\",\"description\":\"Table details\",\"placeholder\":\"Rename and select destination\"},{\"name\":\"append\",\"type\":\"Boolean\",\"title\":\"Append to existing table\",\"value\":false,\"default\":false,\"description\":\"Append to existing table\"},{\"name\":\"optimizationcol\",\"type\":\"Column\",\"title\":\"Cluster by\",\"parent\":\"source\",\"advanced\":true,\"dataType\":[\"geography\",\"boolean\",\"number\",\"string\",\"date\",\"datetime\",\"time\",\"timestamp\"],\"optional\":true,\"providers\":[\"bigquery\"],\"description\":\"Cluster by\"}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":3744,\"y\":0}},{\"id\":\"n_scores\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"*, LEAST(1, GREATEST(0, (relief_ft - 1640) / 4920)) * 0.7 + LEAST(1, GREATEST(0, (elevation_ft - 2625) / 5577)) * 0.3 AS match_mountains, LEAST(1, pct_forest / 100 * 1.4) AS match_forest, LEAST(1, (pct_shrub + pct_barren) / 100) * LEAST(1, GREATEST(0, (19.7 - annual_precip_in) / 13.8)) * 0.85 + LEAST(1, LOG10(1 + hotels_nearby) / LOG10(1001)) * 0.15 AS match_desert, LEAST(1, (pct_grass + pct_crop) / 100 * 1.2) * LEAST(1, GREATEST(0, (2625 - relief_ft) / 1640)) AS match_plains, (IF(ST_INTERSECTS(ST_GEOGFROMTEXT('POLYGON((-113.9 37.0,-113.6 35.9,-111.8 34.6,-109.5 34.4,-107.5 35.0,-106.6 36.6,-107.5 39.3,-109.8 40.0,-111.5 39.5,-112.9 37.9,-113.9 37.0))'), ST_GEOGPOINT(lon, lat)), 0.5, 0) + LEAST(1, (pct_barren * 2 + pct_shrub) / 100) * 0.3 + LEAST(1, GREATEST(0, (relief_ft - 984) / 3937)) * 0.2) * LEAST(1, GREATEST(0, (23.6 - annual_precip_in) / 15.7)) AS match_canyon, LEAST(1, GREATEST(0, (elevation_max_ft - 9186) / 4921)) * 0.6 + IF(elevation_max_ft > 8202, LEAST(1, (pct_snow + pct_barren) / 100 * 3), 0) * 0.4 AS match_alpine, LEAST(1, (pct_wetland + pct_water * 0.3) / 100 * 4) AS match_wetland, LEAST(1, incentive_pct / 40) AS incentive_score, LEAST(1, LOG10(1 + hotels_nearby) / LOG10(3001)) AS hotel_score, 0.5 * LEAST(1, LOG10(1 + healthcare_nearby) / LOG10(5001)) + 0.5 * LEAST(1, GREATEST(0, (60 - IFNULL(nearest_hospital_mi, 250)) / 40)) AS healthcare_score, LEAST(1, GREATEST(0, (150 - IFNULL(nearest_airport_mi, 300)) / 120)) AS airport_score\",\"description\":\"SELECT statement\",\"placeholder\":\"E.g.: *, distance_in_km * 1000 AS distance_in_meters\",\"allowExpressions\":false}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":3456,\"y\":0}},{\"id\":\"n_summary\",\"data\":{\"name\":\"native.select\",\"type\":\"generic\",\"label\":\"Select\",\"inputs\":[{\"name\":\"table\",\"type\":\"Table\",\"title\":\"Source table\",\"optional\":true,\"description\":\"Source table\"},{\"name\":\"select\",\"type\":\"StringSql\",\"title\":\"SELECT statement\",\"value\":\"*, ROUND((incentive_score + hotel_score + healthcare_score + airport_score) / 4, 2) AS logistics_score_equal, ROUND(GREATEST(match_mountains, match_forest, match_desert, match_canyon, match_plains, match_alpine, match_wetland), 2) AS best_landscape_match, CASE WHEN GREATEST(match_mountains, match_forest, match_desert, match_canyon, match_plains, match_alpine, match_wetland) < 0.4 THEN 'Mixed / no strong type' WHEN GREATEST(match_mountains, match_forest, match_desert, match_canyon, match_plains, match_alpine, match_wetland) = match_alpine THEN 'Alpine' WHEN GREATEST(match_mountains, match_forest, match_desert, match_canyon, match_plains, match_alpine, match_wetland) = match_wetland THEN 'Wetland' WHEN GREATEST(match_mountains, match_forest, match_desert, match_canyon, match_plains, match_alpine, match_wetland) = match_canyon THEN 'Canyon' WHEN GREATEST(match_mountains, match_forest, match_desert, match_canyon, match_plains, match_alpine, match_wetland) = match_mountains THEN 'Mountains' WHEN GREATEST(match_mountains, match_forest, match_desert, match_canyon, match_plains, match_alpine, match_wetland) = match_forest THEN 'Forest' WHEN GREATEST(match_mountains, match_forest, match_desert, match_canyon, match_plains, match_alpine, match_wetland) = match_desert THEN 'Desert' ELSE 'Plains' END AS best_landscape\",\"description\":\"SELECT statement\",\"placeholder\":\"E.g.: *, distance_in_km * 1000 AS distance_in_meters\",\"allowExpressions\":false}],\"version\":\"1\"},\"type\":\"generic\",\"position\":{\"x\":3600,\"y\":0}},{\"id\":\"note_overview\",\"data\":{\"name\":\"Note\",\"color\":\"#E5E5E5\",\"genAi\":false,\"label\":\"\",\"width\":360,\"height\":820,\"inputs\":[],\"markdown\":\"---\\nlabel: Workflow 2 \\u00b7 Logistics\\n---\\n## 2 \\u00b7 Logistics\\nAdds what it takes to shoot in each scouting area: **film incentives, nearest airport and hospital, hotels and healthcare within about an hour.**\\n\\n**Run after workflow 1** (about 30 s).\\n\\n**Inputs:** `film_scout_landscape` (from 1) and the uploaded `film_incentives` table.\\n\\n**Output:** `film_scout_scoring`, the table both agent tools and the map read.\\n\\n**Sources:** TIGER counties, Overture places, CARTO Spatial Features, state film offices (in `film_incentives`).\",\"position\":{\"x\":0,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":0,\"y\":-300}},{\"id\":\"note_1\",\"data\":{\"name\":\"Note\",\"color\":\"#F6CF71\",\"genAi\":false,\"label\":\"\",\"width\":392,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 1. Scouting areas from workflow 1\\n---\\n- Reads `film_scout_landscape`.\\n- **Select** computes each area's center point, used for every distance below.\",\"position\":{\"x\":408,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":408,\"y\":-300}},{\"id\":\"note_2\",\"data\":{\"name\":\"Note\",\"color\":\"#9EB9F3\",\"genAi\":false,\"label\":\"\",\"width\":568,\"height\":740,\"inputs\":[],\"markdown\":\"---\\nlabel: 2. County, state and film incentives\\n---\\n- **Custom SQL Select** keeps western counties and labels them `County, ST`.\\n- **Distance to nearest** finds each area's nearest county, so coastal and border areas still get one.\\n- **Join** adds the uploaded `film_incentives` row for that county: base rate, location uplift, program and sources.\",\"position\":{\"x\":872,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":872,\"y\":-300}},{\"id\":\"note_3\",\"data\":{\"name\":\"Note\",\"color\":\"#87C55F\",\"genAi\":false,\"label\":\"\",\"width\":568,\"height\":740,\"inputs\":[],\"markdown\":\"---\\nlabel: 3. Nearest hospital and airport\\n---\\n- **Custom SQL Select** (x2) filters Overture places to hospitals and airports by category and name. It's a simple name filter, so some clinics or small airfields can slip through.\\n- **Distance to nearest** (x2): straight-line miles from each area center.\",\"position\":{\"x\":1512,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":1512,\"y\":-300}},{\"id\":\"note_4\",\"data\":{\"name\":\"Note\",\"color\":\"#FE88B1\",\"genAi\":false,\"label\":\"\",\"width\":568,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 4. Hotels and healthcare within about an hour\\n---\\n- **H3 KRing** expands each area to itself plus its 6 neighbors.\\n- **Join** attaches the neighbors' hotel/tourism and healthcare counts.\\n- **Group by** sums them per area: `hotels_nearby`, `healthcare_nearby`.\",\"position\":{\"x\":2152,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":2152,\"y\":-300}},{\"id\":\"note_5\",\"data\":{\"name\":\"Note\",\"color\":\"#C9DB74\",\"genAi\":false,\"label\":\"\",\"width\":568,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 5. Combine\\n---\\nThree **Joins** bring it together: nearby counts, nearest airport, then all landscape columns from workflow 1.\",\"position\":{\"x\":2792,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":2792,\"y\":-300}},{\"id\":\"note_6\",\"data\":{\"name\":\"Note\",\"color\":\"#8BE0A4\",\"genAi\":false,\"label\":\"\",\"width\":264,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 6. Precompute scores\\n---\\n**Select** adds scores that don't depend on the user's question, so the tools stay simple:\\n- `match_mountains`, `match_forest`, `match_desert`, `match_canyon`, `match_plains`, `match_alpine`, `match_wetland` (0-1, from terrain and land cover)\\n- `incentive_score` (40% = full), `hotel_score`, `healthcare_score` (capacity + nearest hospital), `airport_score` (<= 30 mi full, >= 150 mi zero)\\n\\nA second **Select** adds the map-ready summary columns:\\n- `logistics_score_equal` (the four logistics scores, equal weights)\\n- `best_landscape` (the strongest landscape type, or 'Mixed / no strong type' below 0.4) and `best_landscape_match`\",\"position\":{\"x\":3432,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":3432,\"y\":-300}},{\"id\":\"note_7\",\"data\":{\"name\":\"Note\",\"color\":\"#B497E7\",\"genAi\":false,\"label\":\"\",\"width\":216,\"height\":540,\"inputs\":[],\"markdown\":\"---\\nlabel: 7. Save\\n---\\n**Save as Table** \\u2192 `film_scout_scoring` (one row per scouting area, everything the tools need).\",\"position\":{\"x\":3720,\"y\":-300}},\"type\":\"note\",\"zIndex\":-1,\"position\":{\"x\":3720,\"y\":-300}}],\"edges\":[{\"id\":\"e1\",\"source\":\"s1\",\"target\":\"n2\",\"sourceHandle\":\"out\",\"targetHandle\":\"table\"},{\"id\":\"e2\",\"source\":\"s3\",\"target\":\"n4\",\"sourceHandle\":\"out\",\"targetHandle\":\"sourcea\"},{\"id\":\"e3\",\"source\":\"n2\",\"target\":\"n5\",\"sourceHandle\":\"result\",\"targetHandle\":\"main\"},{\"id\":\"e4\",\"source\":\"n4\",\"target\":\"n5\",\"sourceHandle\":\"result\",\"targetHandle\":\"secondary\"},{\"id\":\"e5\",\"source\":\"n5\",\"target\":\"n7\",\"sourceHandle\":\"result\",\"targetHandle\":\"lefttable\"},{\"id\":\"e6\",\"source\":\"s6\",\"target\":\"n7\",\"sourceHandle\":\"out\",\"targetHandle\":\"righttable\"},{\"id\":\"e7\",\"source\":\"s8\",\"target\":\"n9\",\"sourceHandle\":\"out\",\"targetHandle\":\"sourcea\"},{\"id\":\"e8\",\"source\":\"s8\",\"target\":\"n10\",\"sourceHandle\":\"out\",\"targetHandle\":\"sourcea\"},{\"id\":\"e9\",\"source\":\"n2\",\"target\":\"n11\",\"sourceHandle\":\"result\",\"targetHandle\":\"main\"},{\"id\":\"e10\",\"source\":\"n10\",\"target\":\"n11\",\"sourceHandle\":\"result\",\"targetHandle\":\"secondary\"},{\"id\":\"e11\",\"source\":\"n7\",\"target\":\"n12\",\"sourceHandle\":\"result\",\"targetHandle\":\"main\"},{\"id\":\"e12\",\"source\":\"n9\",\"target\":\"n12\",\"sourceHandle\":\"result\",\"targetHandle\":\"secondary\"},{\"id\":\"e13\",\"source\":\"s1\",\"target\":\"n13\",\"sourceHandle\":\"out\",\"targetHandle\":\"source\"},{\"id\":\"e14